<?php

namespace App\Services;

use Illuminate\Support\Facades\Log;

class HomeSzService
{
    protected $con;
    protected $sql;
    public function __construct()
    {
        //更改成读取config/database.php
        $config = config('database.connections.oracle');
        //设置5s超时
        $this->con = oci_connect($config['username'], $config['password'], $config['host'].':'.$config['port'].'/'.$config['database'], "UTF8");
        if (!$this->con) {
            $e = oci_error();
            Log::info('病案首页质控error', ['msg' => 'getFyData：'.htmlentities($e['message'])]);
        }
    }

    /**
     * 获取用户主信息
     * @param $ZYH
     * @return array
     */
    public function getInfoSql()
    {
        $sql = "SELECT NVL(YX_HIS.CI_MR_FP_PAT_CATA.ID_ORG, '') AS hospital_name, NVL(YX_HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') AS AAA28, NVL(YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT, '') AS ZYH_ID, (NVL(YX_HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') || '' || NVL(YX_HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '')) AS MED_REC_ID, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_PAT, '') AS AAA01, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBP' THEN 0 WHEN YX_HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBQ' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBR' THEN 2 WHEN YX_HIS.CI_MR_FP_PAT_CATA.ID_SEX = '' THEN 9 END, '') AS AAA02C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_SEX, '') AS AAA02C_MC, NVL(EN_ENT.DT_BIRTH_PAT, '') AS AAA03, NVL(YX_HIS.CI_MR_FP_PAT_CATA.AGE, '') AS AAA04_1, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_COUNTRY = '156' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_COUNTRY = 'CHN' THEN 1 ELSE 2 END, '') AS AAA05C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_COUNTRY, '') AS AAA05C_MC, NVL(YX_HIS.CI_MR_FP_PAT_CATA.ADDMISSION_WEIGHT, '') AS AAA42, NVL(YX_HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT, '') AS AEN01, NVL(YX_HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_ONE, '') AS AEN01_2, NVL(YX_HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_TWO, '') AS AEN01_3, NVL(YX_HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_THREE, '') AS AEN01_4, NVL(YX_HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_FOUR, '') AS AEN01_5, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '01' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '02' THEN 2 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '03' THEN 3 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '05' THEN 5 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '11' THEN 11 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_NATION = '97' THEN 66 END, '') AS AAA06C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_NATION, '') AS AAA06C_MC, NVL(YX_HIS.CI_MR_FP_PAT_CATA.ID_CODE, '') AS AAA07, NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_MARRY, '') AS AAA08C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_MARRY, '') AS AAA08C_MC, NVL(CI_MR_FP_OTHER_CATA.OUT_HOS_MODE, '') AS AEM01C, NVL(CI_MR_FP_OTHER_CATA.NAME_OUT_HOS_MODE, '') AS AEM01C_MC, NVL(YX_HIS.CI_MR_FP_PAT_CATA.DT_ACPT, '') AS AAB01, NVL(YX_HIS.CI_MR_FP_PAT_CATA.DT_END, '') AS AAC01, NVL(YX_HIS.CI_MR_FP_PAT_CATA.HOSDAYS, '') AS AAC04, NVL(CI_MR_FP_BL_CATA.AMOUNT, '') AS ADA01, NVL(CI_MR_FP_BL_CATA.CMS_SPAMOUNT, '') AS ADA0101, NVL(YX_HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '') AS AAA29, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '1' THEN 2 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '2' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '3' THEN 3 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '9' THEN 9 END, '') AS AAB06C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_REFERALSRC, '') AS AAB06C_MC, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '1.1' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '1.2' THEN 1 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '2.1' THEN 2 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '2.2' THEN 2 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '3.1' THEN 3 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '3.2' THEN 3 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '4' THEN 4 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '5' THEN 5 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '6' THEN 6 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '7' THEN 7 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '8' THEN 8 WHEN YX_HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '9' THEN 99 END, '') AS AAA26C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_PAY_METHOD, '') AS AAA26C_MC, NVL(CI_MR_FP_OTHER_CATA.NAME_IIOUTREASON, '') AS ABG01N, NVL(CI_MR_FP_OTHER_CATA.SD_IIOUTREASON, '') AS ABG01C, NVL(CASE WHEN YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT IS NULL THEN 2 ELSE 1 END , '') AS is_CATA , NVL(CASE WHEN YX_HIS.EN_ENT_IP.SD_STATUS = '25' THEN 1 ELSE 2 END, '') AS in_hospital FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.EN_ENT ON YX_HIS.EN_ENT.ID_ENT = YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT LEFT JOIN YX_HIS.CI_MR_FP_OTHER_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT LEFT JOIN YX_HIS.CI_MR_FP_BL_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_BL_CATA.ID_ENT LEFT JOIN YX_HIS.EN_ENT_IP ON YX_HIS.EN_ENT_IP.ID_ENT= YX_HIS.CI_MR_FP_BL_CATA.ID_ENT";
        return $sql;
    }

    /**
     *获取patient_hospital_info表Sql
     */
    public function getHospitalSql()
    {
        $sql = "SELECT NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_DEP_PHYADM, '') AS AAB02C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_DEP_PHYADM, '') AS LEFT JOIN YX_HIS.CI_MR_FP_BL_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_BL_CATA.ID_ENT AAB03, NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_IN_BED, '') AS AAB11C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_IN_BED, '') AS AAB11N, NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_DEP_PHYDISC, '') AS AAC02C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_DEP_PHYDISC, '') AS AAC02C_MC, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_OUT_BED, '') AS AAC03, NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_OUT_BED, '') AS AAC11C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_DEP_TRANS, '') AS AAD01C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_DEP_TRANS, '') AS ZKKBMC, NVL(CI_MR_FP_OTHER_CATA.NAME_MED_IN_1, '') AS AEM02, NVL(CI_MR_FP_OTHER_CATA.NAME_IS_HAVE_INHOS_PLAN, '') AS AEM03C, NVL(CI_MR_FP_OTHER_CATA.GOAL_INHOS_PLAN, '') AS AEM04, NVL(CI_MR_FP_OTHER_CATA.NAME_AUT_DEAD_PAT, '') AS AEI01C FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_OTHER_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT";
        return $sql;
    }

    //patient_doctor_info表Sql
    public function getDoctorSql()
    {
        $sql =" SELECT NVL(CI_MR_FP_OTHER_CATA.SD_QCP_DOC, '') AS ZKYS_BH, NVL(CI_MR_FP_OTHER_CATA.NAME_QCP_DOC, '') AS AED02, NVL(CI_MR_FP_OTHER_CATA.SD_QCP_NUR, '') AS ZKHS_BH, NVL(CI_MR_FP_OTHER_CATA.NAME_QCP_NUR, '') AS AED03, NVL(CI_MR_FP_OTHER_CATA.QC_DATE, '') AS AED04, NVL(CI_MR_FP_OTHER_CATA.DIROFDEPT, '') AS AEE01, NVL(CI_MR_FP_OTHER_CATA.SD_DIROFDEPT, '') AS AEE01_CODE, NVL(CI_MR_FP_OTHER_CATA.NAME_ZR_DOC, '') AS AEE02, NVL(CI_MR_FP_OTHER_CATA.NAME_ZZ_DOC, '') AS AEE03, NVL(CI_MR_FP_OTHER_CATA.NAME_ZY_DOC, '') AS AEE04, NVL(CI_MR_FP_OTHER_CATA.NAME_LEARN_DOC, '') AS AEE05, NVL(CI_MR_FP_OTHER_CATA.NAME_INTERN_DOC, '') AS AEE07, NVL(CI_MR_FP_OTHER_CATA.SD_INTERN_DOC, '') AS SXYS_BH, NVL(CI_MR_FP_OTHER_CATA.NAME_CODER, '') AS AEE08, NVL(CI_MR_FP_OTHER_CATA.SD_CODER, '') AS BMY_BH, NVL(CI_MR_FP_OTHER_CATA.NAME_EMP_NUR, '') AS AEE10, NVL(CI_MR_FP_OTHER_CATA.SD_EMP_NUR, '') AS ZRHS_BH, NVL(CI_MR_FP_OTHER_CATA.NAME_TEAM_DOC, '') AS YLZZ, NVL(CI_MR_FP_OTHER_CATA.SD_TEAM_DOC, '') AS YLZZ_BH, NVL(CI_MR_FP_OTHER_CATA.SD_ZR_DOC, '') AS AEE02_CODE, NVL(CI_MR_FP_OTHER_CATA.SD_ZZ_DOC, '') AS AEE03_CODE, NVL(CI_MR_FP_OTHER_CATA.SD_ZY_DOC, '') AS AEE04_CODE FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_OTHER_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT ";
        return $sql;
    }

    //patient_contacts_info表sql
    public function getContactsSql()
    {
        $sql = " SELECT NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_CONT, '') AS AAA22, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_CONTTP, '') AS GX_MC, NVL(YX_HIS.CI_MR_FP_PAT_CATA.ADDR_CONT, '') AS AAA24, NVL(YX_HIS.CI_MR_FP_PAT_CATA.TEL_CONT, '') AS AAA25 FROM YX_HIS.CI_MR_FP_PAT_CATA ";
