    {
        $sql = " SELECT NVL(YX_HIS.CI_MR_FP_PAT_CATA.HEALTH_CARD_ID, '') AS JKKH, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_IDTP, '') AS ZJLB_MC, NVL(CI_MR_FP_OTHER_CATA.THREELEV_NUR_DAYS, '') AS SJHL, NVL(CI_MR_FP_OTHER_CATA.TWOLEV_NUR_DAYS, '') AS EJHL, NVL(CI_MR_FP_OTHER_CATA.ONELEV_NUR_DAYS, '') AS YJHL, NVL(CI_MR_FP_OTHER_CATA.SUPERLEV_NUR_DAYS, '') AS TJHL, NVL(CI_MR_FP_OTHER_CATA.NAME_INPATHSTATUS, '') AS LCLJ, NVL(CI_MR_FP_OTHER_CATA.NAME_COMPLETESTATUS, '') AS WCQK, NVL(CI_MR_FP_OTHER_CATA.NAME_VARIATIONSTAUS, '') AS BYQK FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_OTHER_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT ";
        return $sql;
