    //patient_medical_info表
    public function getMedicalSql()
    {
        $sql="SELECT NVL(YX_HIS.CI_MR_FP_PAT_CATA.SD_OUTP_EMER_DI, '') AS ABA01C, NVL(YX_HIS.CI_MR_FP_PAT_CATA.NAME_OUTP_EMER_DI, '') AS ABA01N, NVL(CI_MR_FP_OTHER_CATA.SD_DIPATHOLOGY, '') AS ABF01C, NVL(CI_MR_FP_OTHER_CATA.NAME_DIPATHOLOGY, '') AS ABF01N, NVL(CI_MR_FP_OTHER_CATA.NUM_PATHO, '') AS ABF04, NVL(CI_MR_FP_OTHER_CATA.REASON_HIGHTESTDI, '') AS ABF02C, NVL(CI_MR_FP_OTHER_CATA.NAME_DRUG_ALLERGY, '') AS AEB02C, NVL(CI_MR_FP_OTHER_CATA.ALLERGIC_DRUGS, '') AS AEB01, NVL(CI_MR_FP_OTHER_CATA.NAME_QOM_RECORD, '') AS AED01C, NVL(CI_MR_FP_OTHER_CATA.NAME_BLOOD_TYPE, '') AS AEG01C, NVL(CI_MR_FP_OTHER_CATA.NAME_RH_TYPE, '') AS AEG02C, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_BEF_INHOS_DAYS, '') AS AEJ01, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_BEF_INHOS_HOURS, '') AS AEJ02, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_BEF_INHOS_MINS, '') AS AEJ03, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_INHOS_DAYS, '') AS AEJ04, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_INHOS_HOURS, '') AS AEJ05, NVL(CI_MR_FP_OTHER_CATA.COMA_TIME_INHOS_MINS, '') AS AEJ06, NVL(CI_MR_FP_OTHER_CATA.VENTILATOR_USE_TIME_DAYS, '') AS AEL01_T, NVL(CI_MR_FP_OTHER_CATA.VENTILATOR_USE_TIME_HOURS, '') AS AEL01, NVL(CI_MR_FP_OTHER_CATA.VENTILATOR_USE_TIME_MINUTES, '') AS AEL01_F, NVL(CI_MR_FP_OTHER_CATA.FG_DAY_SURGERY, '') AS SFRJSS FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_OTHER_CATA ON YX_HIS.CI_MR_FP_OTHER_CATA.ID_ENT= YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT  ";
        return $sql;
    }

    //patient_cost_info表sql
    public function getCostSql()
    {
        $sql = " SELECT NVL(CI_MR_FP_BL_CATA.CMS_GMSFEE, '') AS D11, NVL(CI_MR_FP_BL_CATA.CMS_GTOFEE, '') AS D12, NVL(CI_MR_FP_BL_CATA.CMS_NURFEE, '') AS D13, NVL(CI_MR_FP_BL_CATA.CMS_OTHERFEE, '') AS D14, NVL(CI_MR_FP_BL_CATA.DI_PDIFEE, '') AS D15, NVL(CI_MR_FP_BL_CATA.DI_LDIFEE, '') AS D16, NVL(CI_MR_FP_BL_CATA.DI_IDIFEE, '') AS D17, NVL(CI_MR_FP_BL_CATA.DI_CDIFEE, '') AS D18, NVL(CI_MR_FP_BL_CATA.TC_NSTPFEE, '') AS D19, NVL(CI_MR_FP_BL_CATA.TC_CPTFEE, '') AS D19X01, NVL(CI_MR_FP_BL_CATA.TC_STFEE, '') AS D20, NVL(CI_MR_FP_BL_CATA.TC_ANFEE, '') AS D20X01, NVL(CI_MR_FP_BL_CATA.TC_OPFEE, '') AS D20X02, NVL(CI_MR_FP_BL_CATA.RC_RCFEE, '') AS D21, NVL(CI_MR_FP_BL_CATA.TCM_CMTFEE, '') AS D22, NVL(CI_MR_FP_BL_CATA.WM_WMFEE, '') AS D23, NVL(CI_MR_FP_BL_CATA.WM_AGFEE, '') AS D23X01, NVL(CI_MR_FP_BL_CATA.TCMT_CPMFEE, '') AS D24, NVL(CI_MR_FP_BL_CATA.TCMT_CHMFEE, '') AS D25, NVL(CI_MR_FP_BL_CATA.BABP_BFEE, '') AS D26, NVL(CI_MR_FP_BL_CATA.BABP_APFEE, '') AS D27, NVL(CI_MR_FP_BL_CATA.BABP_GPFEE, '') AS D28, NVL(CI_MR_FP_BL_CATA.BABP_BCFFEE, '') AS D29, NVL(CI_MR_FP_BL_CATA.BABP_CFLFEE, '') AS D30, NVL(CI_MR_FP_BL_CATA.SC_DMMFIFEE, '') AS D31, NVL(CI_MR_FP_BL_CATA.SC_DMMFTFEE, '') AS D32, NVL(CI_MR_FP_BL_CATA.SC_DMMFSFEE, '') AS D33, NVL(CI_MR_FP_BL_CATA.OC_OCFEE, '') AS D34 FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_BL_CATA ON YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT= YX_HIS.CI_MR_FP_BL_CATA.ID_ENT ";
