    //
    public function getDiagnosisSql()
    {
        $sql = " SELECT NVL(CI_MR_FP_XYDI_CATA.SORTNO, '') AS DIA_ORDER, NVL(CASE YX_HIS.CI_MR_FP_XYDI_CATA.FG_MAINDI WHEN 'Y' THEN 1 WHEN 'N' THEN 0 ELSE 2 END, '') AS ZZPB, NVL(CI_MR_FP_XYDI_CATA.NAME_DI_TYPE, '') AS LBMC, NVL(CI_MR_FP_XYDI_CATA.SD_DI, '') AS ICD10_ID1, NVL(CI_MR_FP_XYDI_CATA.NAME_DI, '') AS ICD10_NAME, NVL(CI_MR_FP_XYDI_CATA.ID_DISLVL_INP, '') AS RYQK, NVL(CI_MR_FP_XYDI_CATA.SD_TREATMENT_OUTCOME, '') AS CYQK,NVL ( CI_MR_FP_XYDI_CATA.ID_MRFPXYDI, '' ) AS ZDXH FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_DI_CATA ON YX_HIS.CI_MR_FP_DI_CATA.ID_ENT = YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT LEFT JOIN YX_HIS.CI_MR_FP_XYDI_CATA ON YX_HIS.CI_MR_FP_XYDI_CATA.ID_MRFPDI = YX_HIS.CI_MR_FP_DI_CATA.ID_MRFPDI";
        return $sql;
    }

    //operation表sql
    public function getOperationSql()
    {
        $sql = " SELECT (NVL(YX_HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') || '' || NVL(YX_HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '')) AS AAA28, NVL(CI_MR_FP_SUG_CATA.ID_ENT, '') AS ZYH_ID, NVL(CI_MR_FP_SUG_CATA.SD_SUG, '') AS ICD9_ID1, NVL(CI_MR_FP_SUG_CATA.NAME_SUG, '') AS ICD9_NAME, NVL(CI_MR_FP_SUG_CATA.DT_START_SUG, '') AS OPE_DATE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_SUG, '') AS OPE_MAN_NAME, NVL(CI_MR_FP_SUG_CATA.SD_EMP_SUG, '') AS OPE_MAN_CODE, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ASST1, '') AS FRIST_ASSISTANT_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ASST1, '') AS FRIST_ASSISTANT_NAME, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ASST2, '') AS SECOND_ASSISTANT_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ASST2, '') AS SECOND_ASSISTANT_NAME, NVL(CI_MR_FP_SUG_CATA.SD_ANESTP, '') AS HOCUS_WAY_ID, NVL(CI_MR_FP_SUG_CATA.NAME_ANESTP, '') AS HOCUS_WAY_MC, NVL(CI_MR_FP_SUG_CATA.ID_INCICONDI, '') AS INCISION_GRADE_ID, NVL(CI_MR_FP_SUG_CATA.NAME_INCICONDI, '') AS INCISION_GRADE_MC, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ANES, '') AS HOCUS_MAN_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ANES, '') AS HOCUS_MAN_NAME, NVL(CI_MR_FP_SUG_CATA.DT_START_SUG, '') AS START_TIME, NVL(CI_MR_FP_SUG_CATA.DT_END_SUG, '') AS END_TIME, NVL(CI_MR_FP_SUG_CATA.SORTNO, '') AS OPE_ORDER, NVL(CI_MR_FP_SUG_CATA.SD_LVLSUG, '') AS OPE_LEVEL, NVL(CI_MR_FP_SUG_CATA.NAME_LVLSUG, '') AS OPE_LEVEL_MC, NVL(CI_MR_FP_SUG_CATA.SD_CLASS_SUG, '') AS SSPB, NVL(CI_MR_FP_SUG_CATA.NAME_CLASS_SUG, '') AS SSPB_MC, NVL(CI_MR_FP_SUG_CATA.SORTNO, '') AS SFZYSS, NVL(CI_MR_FP_SUG_CATA.SD_INCITP, '') AS QKDJ, NVL(CI_MR_FP_SUG_CATA.NAME_INCITP, '') AS QKDJ_MC, NVL(CI_MR_FP_SUG_CATA.SD_METHOD_SUG, '') AS SSLX, NVL(CI_MR_FP_SUG_CATA.NAME_METHOD_SUG, '') AS SSLX_MC,NVL ( CI_MR_FP_SUG_CATA.ID_MRFPSUG, '' ) AS SSXH FROM YX_HIS.CI_MR_FP_PAT_CATA LEFT JOIN YX_HIS.CI_MR_FP_SUG_CATA ON YX_HIS.CI_MR_FP_SUG_CATA.ID_ENT = YX_HIS.CI_MR_FP_PAT_CATA.ID_ENT";
