    //获取所属院区
    public function getYq($ksCode)
    {
        $sql =  "SELECT NVL(BD_UDIDOC.ID_UDIDOC, '') AS YQ_CODE FROM YX_HIS.BD_UDIDOC  WHERE YX_HIS.BD_UDIDOC.ID_UDIDOCLIST = '@@@@LL200000000002GJ' AND YX_HIS.BD_UDIDOC.CODE = （SELECT NVL(BD_DEP.SD_HOSDISTRICT, '') AS SD_HOSDISTRICT FROM YX_HIS.BD_DEP WHERE YX_HIS.BD_DEP.CODE = '{$ksCode}'）";
        $data = oci_parse($this->con, $sql);
        oci_execute($data, OCI_DEFAULT);
        $result = [];
        while ($row = oci_fetch_assoc($data)) {
            $result[] = $row;
        }
        oci_free_statement($data);
        return $result;
    }

